1	import { CUE_LIBRARY, GO_CUES, NO_GO_CUES } from '../cues/library'
2	import type {
3	  CueDef,
4	  CueDistanceEntry,
5	  Distance,
6	  DrillConfig,
7	  RepRecord,
8	  RepResult,
9	  SessionSummary,
10	} from './types'
11	import {
12	  DISTANCES,
13	  PRE_CUE_MAX_CEILING_MS,
14	  PRE_CUE_MIN_FLOOR_MS,
15	} from './types'
16	import { randInt, type RNG } from './rng'
17	
18	export function pickPreCueDelayMs(rng: RNG, config: DrillConfig): number {
19	  return randInt(rng, config.preCueMinMs, config.preCueMaxMs)
20	}
21	
22	function filterByAllowed(
23	  cues: readonly CueDef[],
24	  allowed: CueDef['id'][] | null,
25	): readonly CueDef[] {
26	  if (!allowed || allowed.length === 0) return cues
27	  const set = new Set(allowed)
28	  return cues.filter((c) => set.has(c.id))
29	}
30	
31	export function pickNextCue(rng: RNG, config: DrillConfig): CueDef {
32	  if (config.distanceAxisEnabled) {
33	    const pool = filterByAllowed(CUE_LIBRARY, config.allowedCueIds)
34	    if (pool.length === 0) {
35	      throw new Error('pickNextCue: empty library after allowedCueIds filter')
36	    }
37	    return pool[Math.floor(rng() * pool.length)]
38	  }
39	  const allowedGo = filterByAllowed(GO_CUES, config.allowedCueIds)
40	  const allowedNoGo = filterByAllowed(NO_GO_CUES, config.allowedCueIds)
41	  const goEmpty = allowedGo.length === 0
42	  const noGoEmpty = allowedNoGo.length === 0
43	  if (goEmpty && noGoEmpty) {
44	    throw new Error('pickNextCue: empty allowedCueIds filter')
45	  }
46	  const wantGo = goEmpty ? false : noGoEmpty ? true : rng() < config.goCueProbability
47	  const pool = wantGo ? allowedGo : allowedNoGo
48	  return pool[Math.floor(rng() * pool.length)]
49	}
50	
51	export function pickDistance(rng: RNG): Distance {
52	  return DISTANCES[Math.floor(rng() * DISTANCES.length)]
53	}
54	
55	export function resolveCueAtDistance(
56	  cue: CueDef,
57	  distance: Distance | null,
58	): CueDistanceEntry {
59	  if (distance !== null && cue.byDistance) {
60	    return cue.byDistance[distance]
61	  }
62	  return { isGo: cue.isGo, expectedResponse: cue.expectedResponse }
63	}
64	
65	export interface ClassifyInput {
66	  isGo: boolean
67	  cueShownAt: number
68	  pressedAt: number | null
69	  responseWindowMs: number
70	  hesitationThresholdMs: number
71	  lateThresholdMs: number
72	  scoreWeights: Record<RepResult, number>
73	}
74	
75	export interface ClassifyOutput {
76	  result: RepResult
77	  reactionMs: number | null
78	  score: number
79	}
80	
81	export function classifyRep(input: ClassifyInput): ClassifyOutput {
82	  const {
83	    isGo,
84	    cueShownAt,
85	    pressedAt,
86	    responseWindowMs,
87	    hesitationThresholdMs,
88	    lateThresholdMs,
89	    scoreWeights,
90	  } = input
91	
92	  if (pressedAt !== null && pressedAt < cueShownAt) {
93	    return wrap('false_start', null, scoreWeights)
94	  }
95	
96	  const pressedInWindow =
97	    pressedAt !== null && pressedAt - cueShownAt <= responseWindowMs
98	
99	  if (!pressedInWindow) {
100	    return wrap(isGo ? 'late' : 'correct_no_go', null, scoreWeights)
101	  }
102	
103	  const dt = Math.round((pressedAt as number) - cueShownAt)
104	  if (!isGo) {
105	    return wrap('false_start', dt, scoreWeights)
106	  }
107	
108	  let result: RepResult
109	  if (dt < hesitationThresholdMs) result = 'correct_go'
110	  else if (dt < lateThresholdMs) result = 'hesitation'
111	  else result = 'late'
112	  return wrap(result, dt, scoreWeights)
113	}
114	
115	export function classifyPreCuePress(
116	  scoreWeights: Record<RepResult, number>,
117	): ClassifyOutput {
118	  return wrap('false_start', null, scoreWeights)
119	}
120	
121	function wrap(
122	  result: RepResult,
123	  reactionMs: number | null,
124	  scoreWeights: Record<RepResult, number>,
125	): ClassifyOutput {
126	  return { result, reactionMs, score: scoreWeights[result] }
127	}
128	
129	export interface ValidationError {
130	  field: keyof DrillConfig
131	  message: string
132	}
133	
134	export function validateDrillConfig(config: DrillConfig): ValidationError[] {
135	  const errors: ValidationError[] = []
136	  if (config.preCueMinMs < PRE_CUE_MIN_FLOOR_MS) {
137	    errors.push({
138	      field: 'preCueMinMs',
139	      message: `must be ≥ ${PRE_CUE_MIN_FLOOR_MS}ms`,
140	    })
141	  }
142	  if (config.preCueMaxMs > PRE_CUE_MAX_CEILING_MS) {
143	    errors.push({
144	      field: 'preCueMaxMs',
145	      message: `must be ≤ ${PRE_CUE_MAX_CEILING_MS}ms`,
146	    })
147	  }
148	  if (config.preCueMinMs > config.preCueMaxMs) {
149	    errors.push({
150	      field: 'preCueMaxMs',
151	      message: 'must be ≥ min',
152	    })
153	  }
154	  if (config.rounds < 1) {
155	    errors.push({ field: 'rounds', message: 'must be ≥ 1' })
156	  }
157	  if (config.workMs < 1_000) {
158	    errors.push({ field: 'workMs', message: 'must be ≥ 1s' })
159	  }
160	  if (config.restMs < 0) {
161	    errors.push({ field: 'restMs', message: 'must be ≥ 0' })
162	  }
163	  if (config.perFalseStartPenalty < 0) {
164	    errors.push({ field: 'perFalseStartPenalty', message: 'must be ≥ 0' })
165	  }
166	  if (config.perHesitationPenalty < 0) {
167	    errors.push({ field: 'perHesitationPenalty', message: 'must be ≥ 0' })
168	  }
169	  if (config.hesitationThresholdMs > config.lateThresholdMs) {
170	    errors.push({
171	      field: 'lateThresholdMs',
172	      message: 'must be ≥ hesitation threshold',
173	    })
174	  }
175	  if (config.lateThresholdMs > config.responseWindowMs) {
176	    errors.push({
177	      field: 'responseWindowMs',
178	      message: 'must be ≥ late threshold',
179	    })
180	  }
181	  if (config.allowedCueIds && config.allowedCueIds.length === 0) {
182	    errors.push({
183	      field: 'allowedCueIds',
184	      message: 'must include at least one cue (or null for all)',
185	    })
186	  }
187	  if (config.allowedCueIds && !config.distanceAxisEnabled) {
188	    const allowed = new Set(config.allowedCueIds)
189	    const hasGo = GO_CUES.some((c) => allowed.has(c.id))
190	    if (!hasGo) {
191	      errors.push({
192	        field: 'allowedCueIds',
193	        message:
194	          'must include at least one go cue when distance axis is disabled',
195	      })
196	    }
197	  }
198	  return errors
199	}
200	
201	export function pendingPenalties(
202	  reps: RepRecord[],
203	  perFalseStart: number,
204	  perHesitation: number,
205	  cleared: number,
206	): number {
207	  const earned = reps.reduce((sum, r) => {
208	    if (r.result === 'false_start') return sum + perFalseStart
209	    if (r.result === 'hesitation') return sum + perHesitation
210	    return sum
211	  }, 0)
212	  return Math.max(0, earned - cleared)
213	}
214	
215	export interface CueBreakdownRow {
216	  cueId: CueDef['id']
217	  reps: number
218	  correct: number
219	  falseStarts: number
220	  hesitations: number
221	  lateMisses: number
222	  avgRtMs: number | null
223	  best10AvgRtMs: number | null
224	}
225	
226	/**
227	 * Mean of the (up to) 10 fastest values. Returns null if the input is empty.
228	 * Phase 5 — single source of truth for the best-10 metric, used by
229	 * cueBreakdown, sessionTrend (per-session best-10), and cueAggregate
230	 * (cross-session best-10).
231	 */
232	export function best10AvgOf(times: number[]): number | null {
233	  if (times.length === 0) return null
234	  const sorted = [...times].sort((a, b) => a - b).slice(0, 10)
235	  return Math.round(sorted.reduce((a, b) => a + b, 0) / sorted.length)
236	}
237	
238	/**
239	 * Reps whose result is correct_go AND whose reactionMs is a real number.
240	 * Single source of truth for the "RT-eligible" rep set; reused by
241	 * cueBreakdown here and by every analytics aggregate.
242	 */
243	export function correctGoTimesOf(reps: RepRecord[]): number[] {
244	  return reps
245	    .filter((r) => r.result === 'correct_go' && r.reactionMs !== null)
246	    .map((r) => r.reactionMs as number)
247	}
248	
249	export function cueBreakdown(reps: RepRecord[]): CueBreakdownRow[] {
250	  const byId = new Map<CueDef['id'], RepRecord[]>()
251	  for (const r of reps) {
252	    const list = byId.get(r.cueId) ?? []
253	    list.push(r)
254	    byId.set(r.cueId, list)
255	  }
256	  return Array.from(byId.entries()).map(([cueId, list]) => {
257	    const correctGoTimes = correctGoTimesOf(list)
258	    const avgRtMs =
259	      correctGoTimes.length === 0
260	        ? null
261	        : Math.round(
262	            correctGoTimes.reduce((a, b) => a + b, 0) / correctGoTimes.length,
263	          )
264	    return {
265	      cueId,
266	      reps: list.length,
267	      correct: list.filter(
268	        (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
269	      ).length,
270	      falseStarts: list.filter((r) => r.result === 'false_start').length,
271	      hesitations: list.filter((r) => r.result === 'hesitation').length,
272	      lateMisses: list.filter((r) => r.result === 'late').length,
273	      avgRtMs,
274	      best10AvgRtMs: best10AvgOf(correctGoTimes),
275	    }
276	  })
277	}
278	
279	export type PriorGoStreakBucket = '0' | '1' | '2' | '3+'
280	
281	export interface AntiRhythmStats {
282	  overallFalseStartRate: number
283	  buckets: Record<PriorGoStreakBucket, { falseStarts: number; total: number }>
284	  narrative: string
285	}
286	
287	function priorGoStreakBucketOf(n: number): PriorGoStreakBucket {
288	  if (n <= 0) return '0'
289	  if (n === 1) return '1'
290	  if (n === 2) return '2'
291	  return '3+'
292	}
293	
294	export function antiRhythmSignal(reps: RepRecord[]): AntiRhythmStats {
295	  const buckets: AntiRhythmStats['buckets'] = {
296	    '0': { falseStarts: 0, total: 0 },
297	    '1': { falseStarts: 0, total: 0 },
298	    '2': { falseStarts: 0, total: 0 },
299	    '3+': { falseStarts: 0, total: 0 },
300	  }
301	  let streak = 0
302	  let totalGoReps = 0
303	  let totalFalseStarts = 0
304	  for (const r of reps) {
305	    if (r.isGo) {
306	      const b = priorGoStreakBucketOf(streak)
307	      buckets[b].total += 1
308	      if (r.result === 'false_start') buckets[b].falseStarts += 1
309	      totalGoReps += 1
310	      if (r.result === 'false_start') totalFalseStarts += 1
311	      streak += 1
312	    } else {
313	      streak = 0
314	    }
315	  }
316	  const overallFalseStartRate =
317	    totalGoReps === 0 ? 0 : totalFalseStarts / totalGoReps
318	
319	  let narrative = 'No rhythm pattern detected.'
320	  let bestBucket: PriorGoStreakBucket | null = null
321	  let bestRate = -1
322	  for (const key of Object.keys(buckets) as PriorGoStreakBucket[]) {
323	    const b = buckets[key]
324	    if (b.total < 3) continue
325	    const rate = b.falseStarts / b.total
326	    if (
327	      rate > bestRate &&
328	      overallFalseStartRate > 0 &&
329	      rate >= overallFalseStartRate * 1.5
330	    ) {
331	      bestRate = rate
332	      bestBucket = key
333	    }
334	  }
335	  if (bestBucket !== null) {
336	    const pct = Math.round(bestRate * 100)
337	    const label =
338	      bestBucket === '0'
339	        ? 'a non-go cue'
340	        : bestBucket === '3+'
341	          ? '3+ consecutive go cues'
342	          : `${bestBucket} consecutive go cue${bestBucket === '1' ? '' : 's'}`
343	    narrative = `False starts most often after ${label} (${pct}%).`
344	  }
345	
346	  return { overallFalseStartRate, buckets, narrative }
347	}
348	
349	export function summarize(reps: RepRecord[]): SessionSummary {
350	  const reactionTimes = reps
351	    .filter((r) => r.result === 'correct_go' && r.reactionMs !== null)
352	    .map((r) => r.reactionMs as number)
353	
354	  const avgReactionMs =
355	    reactionTimes.length === 0
356	      ? null
357	      : Math.round(
358	          reactionTimes.reduce((a, b) => a + b, 0) / reactionTimes.length,
359	        )
360	
361	  return {
362	    reps: reps.length,
363	    correct: reps.filter(
364	      (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
365	    ).length,
366	    falseStarts: reps.filter((r) => r.result === 'false_start').length,
367	    lateMisses: reps.filter((r) => r.result === 'late').length,
368	    hesitations: reps.filter((r) => r.result === 'hesitation').length,
369	    score: reps.reduce((a, r) => a + r.score, 0),
370	    avgReactionMs,
371	  }
372	}
