import { CUE_LIBRARY, GO_CUES, NO_GO_CUES } from '../cues/library'
import type {
  CueDef,
  CueDistanceEntry,
  Distance,
  DrillConfig,
  RepRecord,
  RepResult,
  SessionSummary,
} from './types'
import {
  DISTANCES,
  PRE_CUE_MAX_CEILING_MS,
  PRE_CUE_MIN_FLOOR_MS,
} from './types'
import { randInt, type RNG } from './rng'

export function pickPreCueDelayMs(rng: RNG, config: DrillConfig): number {
  return randInt(rng, config.preCueMinMs, config.preCueMaxMs)
}

function filterByAllowed(
  cues: readonly CueDef[],
  allowed: CueDef['id'][] | null,
): readonly CueDef[] {
  if (!allowed || allowed.length === 0) return cues
  const set = new Set(allowed)
  return cues.filter((c) => set.has(c.id))
}

export function pickNextCue(rng: RNG, config: DrillConfig): CueDef {
  if (config.distanceAxisEnabled) {
    const pool = filterByAllowed(CUE_LIBRARY, config.allowedCueIds)
    if (pool.length === 0) {
      throw new Error('pickNextCue: empty library after allowedCueIds filter')
    }
    return pool[Math.floor(rng() * pool.length)]
  }
  const allowedGo = filterByAllowed(GO_CUES, config.allowedCueIds)
  const allowedNoGo = filterByAllowed(NO_GO_CUES, config.allowedCueIds)
  const goEmpty = allowedGo.length === 0
  const noGoEmpty = allowedNoGo.length === 0
  if (goEmpty && noGoEmpty) {
    throw new Error('pickNextCue: empty allowedCueIds filter')
  }
  const wantGo = goEmpty ? false : noGoEmpty ? true : rng() < config.goCueProbability
  const pool = wantGo ? allowedGo : allowedNoGo
  return pool[Math.floor(rng() * pool.length)]
}

export function pickDistance(rng: RNG): Distance {
  return DISTANCES[Math.floor(rng() * DISTANCES.length)]
}

export function resolveCueAtDistance(
  cue: CueDef,
  distance: Distance | null,
): CueDistanceEntry {
  if (distance !== null && cue.byDistance) {
    return cue.byDistance[distance]
  }
  return { isGo: cue.isGo, expectedResponse: cue.expectedResponse }
}

export interface ClassifyInput {
  isGo: boolean
  cueShownAt: number
  pressedAt: number | null
  responseWindowMs: number
  hesitationThresholdMs: number
  lateThresholdMs: number
  scoreWeights: Record<RepResult, number>
}

export interface ClassifyOutput {
  result: RepResult
  reactionMs: number | null
  score: number
}

export function classifyRep(input: ClassifyInput): ClassifyOutput {
  const {
    isGo,
    cueShownAt,
    pressedAt,
    responseWindowMs,
    hesitationThresholdMs,
    lateThresholdMs,
    scoreWeights,
  } = input

  if (pressedAt !== null && pressedAt < cueShownAt) {
    return wrap('false_start', null, scoreWeights)
  }

  const pressedInWindow =
    pressedAt !== null && pressedAt - cueShownAt <= responseWindowMs

  if (!pressedInWindow) {
    return wrap(isGo ? 'late' : 'correct_no_go', null, scoreWeights)
  }

  const dt = Math.round((pressedAt as number) - cueShownAt)
  if (!isGo) {
    return wrap('false_start', dt, scoreWeights)
  }

  let result: RepResult
  if (dt < hesitationThresholdMs) result = 'correct_go'
  else if (dt < lateThresholdMs) result = 'hesitation'
  else result = 'late'
  return wrap(result, dt, scoreWeights)
}

export function classifyPreCuePress(
  scoreWeights: Record<RepResult, number>,
): ClassifyOutput {
  return wrap('false_start', null, scoreWeights)
}

function wrap(
  result: RepResult,
  reactionMs: number | null,
  scoreWeights: Record<RepResult, number>,
): ClassifyOutput {
  return { result, reactionMs, score: scoreWeights[result] }
}

export interface ValidationError {
  field: keyof DrillConfig
  message: string
}

export function validateDrillConfig(config: DrillConfig): ValidationError[] {
  const errors: ValidationError[] = []
  if (config.preCueMinMs < PRE_CUE_MIN_FLOOR_MS) {
    errors.push({
      field: 'preCueMinMs',
      message: `must be ≥ ${PRE_CUE_MIN_FLOOR_MS}ms`,
    })
  }
  if (config.preCueMaxMs > PRE_CUE_MAX_CEILING_MS) {
    errors.push({
      field: 'preCueMaxMs',
      message: `must be ≤ ${PRE_CUE_MAX_CEILING_MS}ms`,
    })
  }
  if (config.preCueMinMs > config.preCueMaxMs) {
    errors.push({
      field: 'preCueMaxMs',
      message: 'must be ≥ min',
    })
  }
  if (config.rounds < 1) {
    errors.push({ field: 'rounds', message: 'must be ≥ 1' })
  }
  if (config.workMs < 1_000) {
    errors.push({ field: 'workMs', message: 'must be ≥ 1s' })
  }
  if (config.restMs < 0) {
    errors.push({ field: 'restMs', message: 'must be ≥ 0' })
  }
  if (config.perFalseStartPenalty < 0) {
    errors.push({ field: 'perFalseStartPenalty', message: 'must be ≥ 0' })
  }
  if (config.perHesitationPenalty < 0) {
    errors.push({ field: 'perHesitationPenalty', message: 'must be ≥ 0' })
  }
  if (config.hesitationThresholdMs > config.lateThresholdMs) {
    errors.push({
      field: 'lateThresholdMs',
      message: 'must be ≥ hesitation threshold',
    })
  }
  if (config.lateThresholdMs > config.responseWindowMs) {
    errors.push({
      field: 'responseWindowMs',
      message: 'must be ≥ late threshold',
    })
  }
  if (config.allowedCueIds && config.allowedCueIds.length === 0) {
    errors.push({
      field: 'allowedCueIds',
      message: 'must include at least one cue (or null for all)',
    })
  }
  if (config.allowedCueIds && !config.distanceAxisEnabled) {
    const allowed = new Set(config.allowedCueIds)
    const hasGo = GO_CUES.some((c) => allowed.has(c.id))
    if (!hasGo) {
      errors.push({
        field: 'allowedCueIds',
        message:
          'must include at least one go cue when distance axis is disabled',
      })
    }
  }
  return errors
}

export function pendingPenalties(
  reps: RepRecord[],
  perFalseStart: number,
  perHesitation: number,
  cleared: number,
): number {
  const earned = reps.reduce((sum, r) => {
    if (r.result === 'false_start') return sum + perFalseStart
    if (r.result === 'hesitation') return sum + perHesitation
    return sum
  }, 0)
  return Math.max(0, earned - cleared)
}

export interface CueBreakdownRow {
  cueId: CueDef['id']
  reps: number
  correct: number
  falseStarts: number
  hesitations: number
  lateMisses: number
  avgRtMs: number | null
  best10AvgRtMs: number | null
}

/**
 * Mean of the (up to) 10 fastest values. Returns null if the input is empty.
 * Phase 5 — single source of truth for the best-10 metric, used by
 * cueBreakdown, sessionTrend (per-session best-10), and cueAggregate
 * (cross-session best-10).
 */
export function best10AvgOf(times: number[]): number | null {
  if (times.length === 0) return null
  const sorted = [...times].sort((a, b) => a - b).slice(0, 10)
  return Math.round(sorted.reduce((a, b) => a + b, 0) / sorted.length)
}

/**
 * Reps whose result is correct_go AND whose reactionMs is a real number.
 * Single source of truth for the "RT-eligible" rep set; reused by
 * cueBreakdown here and by every analytics aggregate.
 */
export function correctGoTimesOf(reps: RepRecord[]): number[] {
  return reps
    .filter((r) => r.result === 'correct_go' && r.reactionMs !== null)
    .map((r) => r.reactionMs as number)
}

export function cueBreakdown(reps: RepRecord[]): CueBreakdownRow[] {
  const byId = new Map<CueDef['id'], RepRecord[]>()
  for (const r of reps) {
    const list = byId.get(r.cueId) ?? []
    list.push(r)
    byId.set(r.cueId, list)
  }
  return Array.from(byId.entries()).map(([cueId, list]) => {
    const correctGoTimes = correctGoTimesOf(list)
    const avgRtMs =
      correctGoTimes.length === 0
        ? null
        : Math.round(
            correctGoTimes.reduce((a, b) => a + b, 0) / correctGoTimes.length,
          )
    return {
      cueId,
      reps: list.length,
      correct: list.filter(
        (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
      ).length,
      falseStarts: list.filter((r) => r.result === 'false_start').length,
      hesitations: list.filter((r) => r.result === 'hesitation').length,
      lateMisses: list.filter((r) => r.result === 'late').length,
      avgRtMs,
      best10AvgRtMs: best10AvgOf(correctGoTimes),
    }
  })
}

export type PriorGoStreakBucket = '0' | '1' | '2' | '3+'

export interface AntiRhythmStats {
  overallFalseStartRate: number
  buckets: Record<PriorGoStreakBucket, { falseStarts: number; total: number }>
  narrative: string
}

function priorGoStreakBucketOf(n: number): PriorGoStreakBucket {
  if (n <= 0) return '0'
  if (n === 1) return '1'
  if (n === 2) return '2'
  return '3+'
}

export function antiRhythmSignal(reps: RepRecord[]): AntiRhythmStats {
  const buckets: AntiRhythmStats['buckets'] = {
    '0': { falseStarts: 0, total: 0 },
    '1': { falseStarts: 0, total: 0 },
    '2': { falseStarts: 0, total: 0 },
    '3+': { falseStarts: 0, total: 0 },
  }
  let streak = 0
  let totalGoReps = 0
  let totalFalseStarts = 0
  for (const r of reps) {
    if (r.isGo) {
      const b = priorGoStreakBucketOf(streak)
      buckets[b].total += 1
      if (r.result === 'false_start') buckets[b].falseStarts += 1
      totalGoReps += 1
      if (r.result === 'false_start') totalFalseStarts += 1
      streak += 1
    } else {
      streak = 0
    }
  }
  const overallFalseStartRate =
    totalGoReps === 0 ? 0 : totalFalseStarts / totalGoReps

  let narrative = 'No rhythm pattern detected.'
  let bestBucket: PriorGoStreakBucket | null = null
  let bestRate = -1
  for (const key of Object.keys(buckets) as PriorGoStreakBucket[]) {
    const b = buckets[key]
    if (b.total < 3) continue
    const rate = b.falseStarts / b.total
    if (
      rate > bestRate &&
      overallFalseStartRate > 0 &&
      rate >= overallFalseStartRate * 1.5
    ) {
      bestRate = rate
      bestBucket = key
    }
  }
  if (bestBucket !== null) {
    const pct = Math.round(bestRate * 100)
    const label =
      bestBucket === '0'
        ? 'a non-go cue'
        : bestBucket === '3+'
          ? '3+ consecutive go cues'
          : `${bestBucket} consecutive go cue${bestBucket === '1' ? '' : 's'}`
    narrative = `False starts most often after ${label} (${pct}%).`
  }

  return { overallFalseStartRate, buckets, narrative }
}

export function summarize(reps: RepRecord[]): SessionSummary {
  const reactionTimes = reps
    .filter((r) => r.result === 'correct_go' && r.reactionMs !== null)
    .map((r) => r.reactionMs as number)

  const avgReactionMs =
    reactionTimes.length === 0
      ? null
      : Math.round(
          reactionTimes.reduce((a, b) => a + b, 0) / reactionTimes.length,
        )

  return {
    reps: reps.length,
    correct: reps.filter(
      (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
    ).length,
    falseStarts: reps.filter((r) => r.result === 'false_start').length,
    lateMisses: reps.filter((r) => r.result === 'late').length,
    hesitations: reps.filter((r) => r.result === 'hesitation').length,
    score: reps.reduce((a, r) => a + r.score, 0),
    avgReactionMs,
  }
}

import { useMemo } from 'react'
import { useSession, getSessionSummary } from '../store/session'
import { antiRhythmSignal, cueBreakdown } from '../engine/drill'
import { CUE_LIBRARY } from '../cues/library'
import type { CueId } from '../engine/types'

export function SummaryScreen() {
  const reps = useSession((s) => s.reps)
  const reset = useSession((s) => s.reset)
  const start = useSession((s) => s.start)
  const persistError = useSession((s) => s.persistError)
  const inputSource = useSession((s) => s.inputSource)
  const config = useSession((s) => s.config)
  const cleared = useSession((s) => s.cleared)

  const summary = useMemo(() => getSessionSummary(reps), [reps])
  const breakdown = useMemo(() => cueBreakdown(reps), [reps])
  const rhythm = useMemo(() => antiRhythmSignal(reps), [reps])

  const breakdownById = useMemo(() => {
    const m = new Map<CueId, (typeof breakdown)[number]>()
    for (const row of breakdown) m.set(row.cueId, row)
    return m
  }, [breakdown])

  return (
    <div className="screen summary">
      <h1>Session summary</h1>

      {persistError && (
        <div className="banner warn">
          Storage unavailable: {persistError}. Session was kept in memory only.
        </div>
      )}

      <p className="summary-meta">
        Input source: <strong>{inputSource}</strong>
        {config.penaltyCounterEnabled && (
          <> · Cleared {cleared} penalty rep{cleared === 1 ? '' : 's'}</>
        )}
      </p>

      <div className="stats">
        <Stat label="Reps" value={summary.reps} />
        <Stat label="Score" value={summary.score} />
        <Stat label="Correct" value={summary.correct} />
        <Stat label="False starts" value={summary.falseStarts} />
        <Stat label="Hesitations" value={summary.hesitations} />
        <Stat label="Late misses" value={summary.lateMisses} />
        <Stat
          label="Avg reaction"
          value={
            summary.avgReactionMs === null
              ? '—'
              : `${summary.avgReactionMs} ms`
          }
        />
      </div>

      <div className="rhythm-panel" aria-label="anti-rhythm signal">
        <h2>Rhythm pattern</h2>
        <p>{rhythm.narrative}</p>
      </div>

      <h2>By cue</h2>
      <table className="cue-table">
        <thead>
          <tr>
            <th>Cue</th>
            <th>Reps</th>
            <th>Correct</th>
            <th>FS</th>
            <th>Hes</th>
            <th>Late</th>
            <th>Avg RT</th>
            <th>Best-10 RT</th>
          </tr>
        </thead>
        <tbody>
          {CUE_LIBRARY.map((cue) => {
            const row = breakdownById.get(cue.id)
            if (!row) return null
            return (
              <tr key={cue.id}>
                <td>
                  {cue.label}{' '}
                  <span className="tag">{cue.isGo ? 'go' : 'no-go'}</span>
                </td>
                <td>{row.reps}</td>
                <td>{row.correct}</td>
                <td>{row.falseStarts}</td>
                <td>{row.hesitations}</td>
                <td>{row.lateMisses}</td>
                <td>{row.avgRtMs === null ? '—' : `${row.avgRtMs}`}</td>
                <td>
                  {row.best10AvgRtMs === null ? '—' : `${row.best10AvgRtMs}`}
                </td>
              </tr>
            )
          })}
        </tbody>
      </table>

      <div className="actions">
        <button
          type="button"
          className="primary"
          onClick={() => start(config, undefined, inputSource)}
        >
          Start another session
        </button>
        <button type="button" className="link" onClick={() => reset()}>
          Back to start
        </button>
      </div>
    </div>
  )
}

function Stat({ label, value }: { label: string; value: number | string }) {
  return (
    <div className="stat">
      <span className="stat-value">{value}</span>
      <span className="stat-label">{label}</span>
    </div>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { useSession } from '../store/session'
import { pendingPenalties } from '../engine/drill'
import type { RepResult } from '../engine/types'
import { CueStage } from './CueStage'
import { RestScreen } from './RestScreen'
import { startDistanceTone, stopDistanceTone } from '../audio/distanceTone'
import { usePhonePeer } from '../store/phone-peer'

const FEEDBACK_HOLD_MS = 1000

interface TrainerScreenProps {
  commitKeyCode: string
  commitKeyLabel: string
}

export function TrainerScreen({
  commitKeyCode,
  commitKeyLabel,
}: TrainerScreenProps) {
  const phase = useSession((s) => s.phase)
  const current = useSession((s) => s.current)
  const feedback = useSession((s) => s.feedback)
  const config = useSession((s) => s.config)
  const reps = useSession((s) => s.reps)
  const roundIndex = useSession((s) => s.roundIndex)
  const workEndAt = useSession((s) => s.workEndAt)
  const cleared = useSession((s) => s.cleared)
  const inputSource = useSession((s) => s.inputSource)
  const revealCue = useSession((s) => s.revealCue)
  const recordPress = useSession((s) => s.recordPress)
  const finishWindow = useSession((s) => s.finishWindow)
  const acknowledgeFeedback = useSession((s) => s.acknowledgeFeedback)
  const stop = useSession((s) => s.stop)
  const phoneStatus = usePhonePeer((s) => s.status)

  // phaseRef keeps the commit dispatcher stable across phase transitions —
  // otherwise the phone-peer onCommit subscription would re-bind on every
  // rep, churning the slice's handler set. Keyboard's listener doesn't need
  // the ref but reads through it for symmetry.
  const phaseRef = useRef(phase)
  useEffect(() => {
    phaseRef.current = phase
  }, [phase])

  const dispatchCommit = useCallback(
    (at: number) => {
      const p = phaseRef.current
      if (p === 'waiting' || p === 'showing') {
        recordPress(at)
      } else if (p === 'feedback') {
        acknowledgeFeedback()
      }
    },
    [recordPress, acknowledgeFeedback],
  )

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.repeat) return
      if (e.code === commitKeyCode) {
        e.preventDefault()
        dispatchCommit(performance.now())
      } else if (e.key === 'Escape') {
        stop()
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [commitKeyCode, dispatchCommit, stop])

  // Phase 2b.4 — phone-as-input. Phone commits route through the same
  // dispatchCommit the keyboard handler uses so the drill engine's logic
  // (waiting → showing → feedback, hesitation/late thresholds, false-start
  // classification) applies identically across input sources.
  useEffect(() => {
    if (inputSource !== 'phone') return
    return usePhonePeer.getState().onCommit((c) => dispatchCommit(c.receivedAt))
  }, [inputSource, dispatchCommit])

  useEffect(() => {
    if (phase !== 'waiting' || !current || current.cueShownAt !== null) return
    const timer = window.setTimeout(revealCue, current.preCueDelayMs)
    return () => window.clearTimeout(timer)
  }, [phase, current, revealCue])

  useEffect(() => {
    if (phase !== 'showing' || !current?.cueShownAt) return
    const timer = window.setTimeout(finishWindow, config.responseWindowMs)
    return () => window.clearTimeout(timer)
  }, [phase, current, config.responseWindowMs, finishWindow])

  useEffect(() => {
    if (phase !== 'feedback') return
    const timer = window.setTimeout(acknowledgeFeedback, FEEDBACK_HOLD_MS)
    return () => window.clearTimeout(timer)
  }, [phase, acknowledgeFeedback])

  useEffect(() => {
    if (!config.audioToneEnabled) return
    if (phase === 'showing' && current?.distance) {
      startDistanceTone(current.distance)
      return () => stopDistanceTone()
    }
  }, [phase, current?.distance, config.audioToneEnabled])

  const [now, setNow] = useState<number>(() => performance.now())
  useEffect(() => {
    if (workEndAt === null) return
    const interval = window.setInterval(() => setNow(performance.now()), 250)
    return () => window.clearInterval(interval)
  }, [workEndAt])
  const workSecondsRemaining =
    workEndAt === null ? null : Math.max(0, Math.ceil((workEndAt - now) / 1000))

  if (phase === 'rest') {
    return <RestScreen />
  }

  const repsDone = reps.length
  const penalties = config.penaltyCounterEnabled
    ? pendingPenalties(
        reps,
        config.perFalseStartPenalty,
        config.perHesitationPenalty,
        cleared,
      )
    : 0

  const phoneDropped =
    inputSource === 'phone' && phoneStatus !== 'connected'

  return (
    <div
      className={`screen trainer trainer-${
        phase === 'feedback' && feedback ? feedback.rep.result : phase
      }`}
    >
      {phoneDropped && (
        <div
          className="banner warn"
          role="alert"
          data-testid="phone-dropped"
        >
          Phone disconnected ({phoneStatus}) — reconnect to continue.
        </div>
      )}
      <header className="hud">
        <span>
          Round {roundIndex + 1}/{config.rounds}
        </span>
        <span>Rep {repsDone + (phase === 'ended' ? 0 : 1)}</span>
        {workSecondsRemaining !== null && (
          <WorkClock totalSeconds={workSecondsRemaining} />
        )}
        {config.penaltyCounterEnabled && (
          <span className="hud-penalties" aria-label="pending penalty reps">
            +{penalties}
          </span>
        )}
        <button
          type="button"
          className="link"
          onClick={stop}
          aria-label="Stop drill"
        >
          Stop (Esc)
        </button>
      </header>

      <main className="stage">
        {phase === 'waiting' && (
          <div className="ready">
            <span className="ready-label">READY</span>
            <span className="motion-pulse" aria-hidden="true" />
          </div>
        )}

        {phase === 'showing' && current && (
          <CueStage
            cue={current.cue}
            distance={current.distance}
            textOverlayEnabled={config.textOverlayEnabled}
            keyHint={commitKeyLabel}
          />
        )}

        {phase === 'feedback' && feedback && (
          <div className="feedback">
            <span className="feedback-label">
              {feedbackLabel(feedback.rep.result)}
            </span>
            {feedback.rep.reactionMs !== null && (
              <span className="feedback-sub">{feedback.rep.reactionMs} ms</span>
            )}
          </div>
        )}
      </main>
    </div>
  )
}

function WorkClock({ totalSeconds }: { totalSeconds: number }) {
  const m = Math.floor(totalSeconds / 60)
  const s = totalSeconds % 60
  return (
    <span className="hud-clock" aria-label="work time remaining">
      {m}:{s.toString().padStart(2, '0')}
    </span>
  )
}

function feedbackLabel(result: RepResult): string {
  switch (result) {
    case 'correct_go':
      return 'GO ✓'
    case 'correct_no_go':
      return 'HOLD ✓'
    case 'late':
      return 'LATE'
    case 'false_start':
      return 'FALSE START'
    case 'hesitation':
      return 'HESITATION'
  }
}

import { beforeEach, describe, expect, it } from 'vitest'
import { mulberry32 } from '../engine/rng'
import { useSession } from './session'
import { getDb } from './db'

function reset() {
  useSession.getState().reset()
}

async function clearDb() {
  const db = getDb()
  if (!db) return
  await db.reps.clear()
  await db.sessions.clear()
}

describe('useSession store', () => {
  beforeEach(async () => {
    reset()
    await clearDb()
  })

  it('transitions idle → waiting on start with a pre-selected cue', () => {
    useSession.getState().start({}, mulberry32(1))
    const s = useSession.getState()
    expect(s.phase).toBe('waiting')
    expect(s.sessionId).not.toBeNull()
    expect(s.current).not.toBeNull()
    expect(s.current?.cueShownAt).toBeNull()
    expect(s.reps).toEqual([])
  })

  it('press during waiting (pre-cue) records a false_start rep', () => {
    useSession.getState().start({}, mulberry32(2))
    const before = useSession.getState().reps.length
    useSession.getState().recordPress(performance.now())
    const after = useSession.getState()
    expect(after.reps.length).toBe(before + 1)
    expect(after.reps[after.reps.length - 1].result).toBe('false_start')
    expect(after.phase).toBe('feedback')
  })

  it('press after revealCue on a go cue records correct_go with reaction time', () => {
    useSession.getState().start(
      { goCueProbability: 1, hesitationThresholdMs: 600 },
      mulberry32(3),
    )
    useSession.getState().revealCue()
    const cueShownAt = useSession.getState().current?.cueShownAt as number
    useSession.getState().recordPress(cueShownAt + 200)
    const rep = useSession.getState().reps.at(-1)
    expect(rep?.result).toBe('correct_go')
    expect(rep?.reactionMs).toBe(200)
    expect(useSession.getState().phase).toBe('feedback')
