        pool: tagged,
        currentClip: null,
        previousClipId: null,
        clipStartedAt: null,
        cueShownAt: null,
        reps: [],
        feedback: null,
        persistError: null,
      })
      persistSession(null)
      get().selectNextClip()
    },

    selectNextClip: () => {
      const { pool, previousClipId, rng, phase } = get()
      if (phase === 'ended' || pool.length === 0) return
      const ids = pool.map((c) => c.id)
