        <ClipLibraryScreen
          onClose={() => setView('idle')}
          onTagClip={(clipId) => {
            setTaggingClipId(clipId)
            setView('tag')
          }}
        />
      </Suspense>
    )
  }
  if (view === 'tag' && taggingClipId) {
    return (
      <Suspense fallback={<div className="screen">Loading tag editor…</div>}>
        <ClipTagScreen
          clipId={taggingClipId}
