    sessionStartedAt: null,
    config: DEFAULT_DRILL_CONFIG,
    rng: defaultRng,
    inputSource: 'keyboard',
    pool: [],
    currentClip: null,
    previousClipId: null,
    clipStartedAt: null,
    cueShownAt: null,
    reps: [],
    feedback: null,
