      const { phase, config, reps } = get()
      if (phase !== 'feedback') return
      if (config.maxReps !== null && reps.length >= config.maxReps) {
        get().stop()
        return
      }
      get().selectNextClip()
    },

    stop: () => {
      persistSession(Date.now())
      set({
        phase: 'ended',
        currentClip: null,
        clipStartedAt: null,
        cueShownAt: null,
