        phase: 'idle',
        sessionId: null,
        sessionStartedAt: null,
        pool: [],
        currentClip: null,
        previousClipId: null,
        clipStartedAt: null,
        cueShownAt: null,
        reps: [],
        feedback: null,
        persistError: null,
      })
