import { useCallback, useEffect, useRef } from 'react'
import { useClipRunner } from '../clipmode/runner'
import { usePhonePeer } from '../store/phone-peer'
import { CueStage } from './CueStage'
import { CUE_LIBRARY } from '../cues/library'
import type { RepResult } from '../engine/types'

const FEEDBACK_HOLD_MS = 1000

interface ClipDrillScreenProps {
  commitKeyCode: string
  commitKeyLabel: string
}

interface RvfcMetadata {
  mediaTime: number
}

type RvfcCallback = (now: number, metadata: RvfcMetadata) => void

interface VideoMaybeRvfc {
  requestVideoFrameCallback?: (cb: RvfcCallback) => number
  cancelVideoFrameCallback?: (handle: number) => void
}

function asMaybeRvfc(v: HTMLVideoElement | null): VideoMaybeRvfc | null {
  return v as unknown as VideoMaybeRvfc | null
}

export function ClipDrillScreen({
  commitKeyCode,
  commitKeyLabel,
}: ClipDrillScreenProps) {
  const phase = useClipRunner((s) => s.phase)
  const currentClip = useClipRunner((s) => s.currentClip)
  const playSeq = useClipRunner((s) => s.playSeq)
  const feedback = useClipRunner((s) => s.feedback)
  const reps = useClipRunner((s) => s.reps)
  const inputSource = useClipRunner((s) => s.inputSource)
  const config = useClipRunner((s) => s.config)
  const markClipStarted = useClipRunner((s) => s.markClipStarted)
  const markCueShown = useClipRunner((s) => s.markCueShown)
  const recordPress = useClipRunner((s) => s.recordPress)
  const finishWindow = useClipRunner((s) => s.finishWindow)
  const acknowledgeFeedback = useClipRunner((s) => s.acknowledgeFeedback)
  const stop = useClipRunner((s) => s.stop)
  const phoneStatus = usePhonePeer((s) => s.status)

  const videoRef = useRef<HTMLVideoElement>(null)
  const blobUrlRef = useRef<string | null>(null)
  const phaseRef = useRef(phase)
  useEffect(() => {
    phaseRef.current = phase
  }, [phase])

  const dispatchCommit = useCallback(
    (at: number) => {
      const p = phaseRef.current
      if (p === 'precue' || p === 'showing') {
        recordPress(at)
      } else if (p === 'feedback') {
        acknowledgeFeedback()
      }
    },
    [recordPress, acknowledgeFeedback],
  )

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.repeat) return
      if (e.code === commitKeyCode) {
        e.preventDefault()
        dispatchCommit(performance.now())
      } else if (e.key === 'Escape') {
        stop()
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [commitKeyCode, dispatchCommit, stop])

  useEffect(() => {
    if (inputSource !== 'phone') return
    return usePhonePeer.getState().onCommit((c) => dispatchCommit(c.receivedAt))
  }, [inputSource, dispatchCommit])

  // Mount the current clip's blob URL on the <video>; revoke on unmount /
  // when the clip changes. Mirrors ClipTagScreen's effect shape.
  useEffect(() => {
    const v = videoRef.current
    if (!v || !currentClip) return
    let url: string
    try {
      url = URL.createObjectURL(currentClip.blob)
    } catch {
      return
    }
    blobUrlRef.current = url
    v.src = url
    v.currentTime = 0
    void v.play().catch(() => {
      /* play() can reject if the browser blocks autoplay; the rvfc
         loop still fires once play eventually starts. */
    })
    return () => {
      URL.revokeObjectURL(url)
      blobUrlRef.current = null
    }
  }, [currentClip])

  // Schedule rvfc to detect when the playhead crosses `cueAtMs`. Per §B5,
  // requestVideoFrameCallback is the only path to ±33 ms precision; this
  // hook only runs when the prototype shipped it (gated upstream by
  // `isClipModeSupported()`).
  useEffect(() => {
    if (phase !== 'precue' || !currentClip) return
    const rvfc = asMaybeRvfc(videoRef.current)
    if (!rvfc || typeof rvfc.requestVideoFrameCallback !== 'function') return
    const target = currentClip.cueAtMs ?? 0
    let cancelled = false
    let handle: number | null = null
    const tick: RvfcCallback = (_now, metadata) => {
      if (cancelled) return
      if (metadata.mediaTime * 1000 >= target) {
        markCueShown(performance.now())
        return
      }
      handle = rvfc.requestVideoFrameCallback!(tick)
    }
    handle = rvfc.requestVideoFrameCallback(tick)
    return () => {
      cancelled = true
      if (
        handle !== null &&
        typeof rvfc.cancelVideoFrameCallback === 'function'
      ) {
        rvfc.cancelVideoFrameCallback(handle)
      }
    }
  }, [phase, currentClip, markCueShown])

  // Auto-finish the response window once cueShownAt has been set and the
  // configured responseWindowMs elapses with no press.
  useEffect(() => {
    if (phase !== 'showing') return
    const timer = window.setTimeout(finishWindow, config.responseWindowMs)
    return () => window.clearTimeout(timer)
  }, [phase, config.responseWindowMs, finishWindow])

  useEffect(() => {
    if (phase !== 'feedback') return
    const timer = window.setTimeout(acknowledgeFeedback, FEEDBACK_HOLD_MS)
    return () => window.clearTimeout(timer)
  }, [phase, acknowledgeFeedback])

  const phoneDropped =
    inputSource === 'phone' && phoneStatus !== 'connected'

  const cue =
    currentClip?.cueId !== undefined
      ? CUE_LIBRARY.find((c) => c.id === currentClip.cueId) ?? null
      : null

  return (
    <div
      className={`screen trainer clip-drill trainer-${
        phase === 'feedback' && feedback ? feedback.rep.result : phase
      }`}
      data-testid="clip-drill"
    >
      {phoneDropped && (
        <div className="banner warn" role="alert" data-testid="phone-dropped">
          Phone disconnected ({phoneStatus}) — reconnect to continue.
        </div>
      )}
      <header className="hud">
        <span>Clip mode</span>
        <span>Rep {reps.length + (phase === 'ended' ? 0 : 1)}</span>
        <button
          type="button"
          className="link"
          onClick={stop}
          aria-label="Stop clip drill"
        >
          Stop (Esc)
        </button>
      </header>

      <main className="stage clip-drill-stage">
        <video
          ref={videoRef}
          className="clip-drill-video"
          data-testid="clip-drill-video"
          playsInline
          muted
          onPlaying={() => markClipStarted(performance.now())}
        />

        {phase === 'precue' && (
          <div className="ready">
            <span className="ready-label">WATCH</span>
          </div>
        )}

        {phase === 'showing' && cue && (
          <CueStage
            cue={cue}
            distance={null}
            textOverlayEnabled={false}
            keyHint={commitKeyLabel}
          />
        )}

        {phase === 'feedback' && feedback && (
          <div className="feedback">
            <span className="feedback-label">
              {feedbackLabel(feedback.rep.result)}
            </span>
            {feedback.rep.reactionMs !== null && (
              <span className="feedback-sub">{feedback.rep.reactionMs} ms</span>
            )}
          </div>
        )}
      </main>
    </div>
  )
}

function feedbackLabel(result: RepResult): string {
  switch (result) {
    case 'correct_go':
      return 'GO ✓'
    case 'correct_no_go':
      return 'HOLD ✓'
    case 'late':
      return 'LATE'
    case 'false_start':
      return 'FALSE START'
    case 'hesitation':
      return 'HESITATION'
  }
}

import { beforeEach, describe, expect, it } from 'vitest'
import { mulberry32 } from '../engine/rng'
import { getDb } from '../store/db'
import { useClipRunner, selectTaggedClips } from './runner'
import type { ClipRecord } from './types'

function makeClip(over: Partial<ClipRecord> = {}): ClipRecord {
  return {
    id: over.id ?? 'clip-1',
    name: over.name ?? 'clip-1.mp4',
    mimeType: 'video/mp4',
    durationMs: over.durationMs ?? 4000,
    sizeBytes: 1024,
    importedAt: over.importedAt ?? 1000,
    blob: new Blob(['x'], { type: 'video/mp4' }),
    cueId: over.cueId,
    cueAtMs: over.cueAtMs,
  }
}

function taggedClip(id: string, cueId: ClipRecord['cueId'], cueAtMs: number) {
  return makeClip({ id, cueId, cueAtMs })
}

async function clearDb() {
  const db = getDb()
  if (!db) return
  await db.reps.clear()
  await db.sessions.clear()
}

function flush() {
  return Promise.resolve()
}

describe('selectTaggedClips', () => {
  it('keeps clips with both cueId and cueAtMs set', () => {
    const tagged = taggedClip('a', 'blitzes', 1000)
    const partial = makeClip({ id: 'b', cueId: 'blitzes' /* no cueAtMs */ })
    const untagged = makeClip({ id: 'c' })
    expect(selectTaggedClips([tagged, partial, untagged])).toEqual([tagged])
  })

  it('returns an empty array when no clips are tagged', () => {
    expect(selectTaggedClips([makeClip(), makeClip({ id: 'x' })])).toEqual([])
  })
})

describe('useClipRunner', () => {
  beforeEach(async () => {
    useClipRunner.getState().reset()
    await clearDb()
  })

  it('start with an empty tagged pool is a no-op (stays idle)', () => {
    useClipRunner.getState().start([makeClip()], {}, mulberry32(1))
    const s = useClipRunner.getState()
    expect(s.phase).toBe('idle')
    expect(s.sessionId).toBeNull()
  })

  it('start picks an initial clip and transitions to precue', () => {
    const clips = [
      taggedClip('a', 'blitzes', 500),
      taggedClip('b', 'steps_in', 800),
    ]
    useClipRunner.getState().start(clips, { maxReps: 5 }, mulberry32(1))
    const s = useClipRunner.getState()
    expect(s.phase).toBe('precue')
    expect(s.sessionId).not.toBeNull()
    expect(s.currentClip).not.toBeNull()
    expect(['a', 'b']).toContain(s.currentClip?.id)
    expect(s.config.maxReps).toBe(5)
    expect(s.reps).toEqual([])
  })

  it('markClipStarted + markCueShown advance phase to "showing" with cueShownAt set', () => {
    useClipRunner
      .getState()
      .start([taggedClip('a', 'blitzes', 500)], {}, mulberry32(1))
    useClipRunner.getState().markClipStarted(10_000)
    useClipRunner.getState().markCueShown(10_500)
    const s = useClipRunner.getState()
    expect(s.phase).toBe('showing')
    expect(s.cueShownAt).toBe(10_500)
    expect(s.clipStartedAt).toBe(10_000)
  })

  it('recordPress within hesitation threshold on a go cue → correct_go with clipId', () => {
    useClipRunner
      .getState()
      .start(
        [taggedClip('alpha', 'blitzes', 500)],
        { hesitationThresholdMs: 600 },
        mulberry32(1),
      )
    useClipRunner.getState().markClipStarted(0)
    useClipRunner.getState().markCueShown(1000)
    useClipRunner.getState().recordPress(1300)
    const s = useClipRunner.getState()
    const rep = s.reps.at(-1)
    expect(s.phase).toBe('feedback')
    expect(rep?.result).toBe('correct_go')
    expect(rep?.reactionMs).toBe(300)
    expect(rep?.clipId).toBe('alpha')
    expect(rep?.inputSource).toBe('keyboard')
  })

  it('recordPress before cue (during precue) records a false_start with clipId', () => {
    useClipRunner
      .getState()
      .start([taggedClip('alpha', 'blitzes', 500)], {}, mulberry32(1))
    useClipRunner.getState().markClipStarted(0)
    useClipRunner.getState().recordPress(200) // before cue
    const s = useClipRunner.getState()
    const rep = s.reps.at(-1)
    expect(rep?.result).toBe('false_start')
    expect(rep?.clipId).toBe('alpha')
    expect(s.phase).toBe('feedback')
  })

  it('finishWindow with no press on a go cue records late with clipId', () => {
    useClipRunner
      .getState()
      .start([taggedClip('alpha', 'blitzes', 500)], {}, mulberry32(1))
    useClipRunner.getState().markClipStarted(0)
    useClipRunner.getState().markCueShown(1000)
    useClipRunner.getState().finishWindow()
    const rep = useClipRunner.getState().reps.at(-1)
    expect(rep?.result).toBe('late')
    expect(rep?.clipId).toBe('alpha')
  })

  it('acknowledgeFeedback after a rep selects the next clip', () => {
    const clips = [
      taggedClip('a', 'blitzes', 500),
      taggedClip('b', 'steps_in', 500),
    ]
    useClipRunner.getState().start(clips, {}, mulberry32(1))
    useClipRunner.getState().markClipStarted(0)
    useClipRunner.getState().markCueShown(1000)
    useClipRunner.getState().recordPress(1300)
    const first = useClipRunner.getState().currentClip?.id
    useClipRunner.getState().acknowledgeFeedback()
    const s = useClipRunner.getState()
    expect(s.phase).toBe('precue')
    expect(s.currentClip?.id).not.toBe(first) // no-immediate-repeat
  })

  it('acknowledgeFeedback at maxReps ends the session and persists with mode="clip"', async () => {
    useClipRunner
      .getState()
      .start(
        [taggedClip('a', 'blitzes', 500), taggedClip('b', 'steps_in', 500)],
        { maxReps: 1 },
        mulberry32(1),
      )
    useClipRunner.getState().markClipStarted(0)
    useClipRunner.getState().markCueShown(1000)
    useClipRunner.getState().recordPress(1300)
    useClipRunner.getState().acknowledgeFeedback()
    const s = useClipRunner.getState()
    expect(s.phase).toBe('ended')
    await flush()
    await flush()
    const db = getDb()
    const sessionId = s.sessionId
    if (!db || !sessionId) throw new Error('db/session unavailable')
    const stored = await db.sessions.get(sessionId)
    expect(stored?.mode).toBe('clip')
    expect(stored?.endedAt).not.toBeNull()
    expect(stored?.repCount).toBe(1)
  })

  it('stop() persists the session with mode="clip" and endedAt set', async () => {
    useClipRunner
      .getState()
      .start([taggedClip('a', 'blitzes', 500)], {}, mulberry32(1))
    useClipRunner.getState().stop()
    await flush()
    await flush()
    const sessionId = useClipRunner.getState().sessionId
    if (!sessionId) throw new Error('sessionId missing')
    const db = getDb()
    const stored = await db?.sessions.get(sessionId)
    expect(stored?.mode).toBe('clip')
    expect(stored?.endedAt).not.toBeNull()
  })

  it('records inputSource onto each rep (Phase 6.3 cross-cut for phone/pedal/keyboard)', () => {
    useClipRunner
      .getState()
      .start(
        [taggedClip('a', 'blitzes', 500)],
        {},
        mulberry32(1),
        'phone',
      )
    useClipRunner.getState().markClipStarted(0)
    useClipRunner.getState().markCueShown(1000)
    useClipRunner.getState().recordPress(1200)
    expect(useClipRunner.getState().reps.at(-1)?.inputSource).toBe('phone')
  })
})

